python -c "import yaml,json; p=yaml.safe_load(open(r'C:\Users\carys\.cursor\skills\nd-code-analyzer\references\nd-patterns.yaml')); pats=p['patterns']; print('total',len(pats)); 
for x in pats:
  print(x['id'], x['severity_default'], x['category'], x['tier'], x['name'][:60])"

$ErrorActionPreference = 'Stop'
$rg = "c:\Users\carys\AppData\Local\Programs\cursor\resources\app\node_modules\@vscode\ripgrep\bin\rg.exe"
$root = "C:\Users\carys\cts"
$cands = (Get-Content "C:\Users\carys\.cursor\plans\nd_cts_candidates.json" -Raw | ConvertFrom-Json).candidates

function Get-Context($rel, $line, $before=8, $after=12) {
  $path = Join-Path $root ($rel -replace '/','\')
  if (-not (Test-Path $path)) { return $null }
  $lines = Get-Content $path
  $i = [Math]::Max(0, $line-1-$before)
  $j = [Math]::Min($lines.Count-1, $line-1+$after)
  $sb = New-Object System.Text.StringBuilder
  for ($k=$i; $k -le $j; $k++) {
    $mark = if (($k+1) -eq $line) { '>>>' } else { '   ' }
    [void]$sb.AppendLine(("{0}{1,5}|{2}" -f $mark, ($k+1), $lines[$k]))
  }
  return $sb.ToString()
}

# Narrow 1.1: keep only sorts that look like 2-arg (no comparator comma before closing) OR pointer-ish
$n11 = @()
foreach ($c in ($cands | Where-Object pattern_id -eq '1.1')) {
  $s = $c.snippet
  # skip if comparator lambda/functor obvious on same line
  if ($s -match ',\s*(?:\[[^\]]*\]|ndmObjectHandleNS|dosContainer|Compare|compare|less|greater|keyCompare)') { continue }
  # keep if 2-arg form ends with ); or multi-line start without comparator on same line
  if ($s -match 'std::(?:stable_)?sort\s*\([^,)]+\.begin\(\)\s*,\s*[^,)]+\.end\(\)\s*\)\s*;') {
    $n11 += $c; continue
  }
  # multi-line / ambiguous — keep for triage if not obviously 3-arg on one line
  if ($s -notmatch ',\s*[^,)]+\)\s*;') { $n11 += $c }
}
Write-Host "1.1 narrowed: $($n11.Count)"

# Narrow 1.2: only keep if same file also iterates that container-ish OR declaration looks raw pointer without comparator on same line
$n12 = @()
$setDecls = $cands | Where-Object pattern_id -eq '1.2'
# group by file
$byFile = $setDecls | Group-Object file
foreach ($g in $byFile) {
  $path = Join-Path $root ($g.Name -replace '/','\')
  if (-not (Test-Path $path)) { continue }
  $text = Get-Content $path -Raw
  # skip if file only uses find/count/insert/erase patterns and never range-for over pointer containers — cheap heuristic: require range-for OR begin()/end() iteration beyond the declaration
  $hasIter = ($text -match 'for\s*\([^:]+:') -or ($text -match '\.begin\(\)')
  foreach ($c in $g.Group) {
    $s = $c.snippet
    if ($s -match ',\s*(?:ndmObjectHandleNS|dosContainer|Compare|compare|keyCompare|less|PtrCmp|ObjCmp)') { continue }
    if ($s -match 'std::(?:set|map|multiset|multimap)\s*<\s*[A-Za-z_][A-Za-z0-9_:]*\s*\*\s*,') {
      # has third template arg - likely custom comparator
      if ($s -match ',\s*[^>]+>') { continue }
    }
    if (-not $hasIter) { continue }
    $n12 += $c
  }
}
Write-Host "1.2 narrowed: $($n12.Count) (from $($setDecls.Count))"

# Narrow 1.3 similarly
$n13 = @()
$uDecls = $cands | Where-Object pattern_id -eq '1.3'
$byFile3 = $uDecls | Group-Object file
foreach ($g in $byFile3) {
  $path = Join-Path $root ($g.Name -replace '/','\')
  if (-not (Test-Path $path)) { continue }
  $text = Get-Content $path -Raw
  $hasIter = ($text -match 'for\s*\([^:]+:') 
  foreach ($c in $g.Group) {
    $s = $c.snippet
    if ($s -match ',\s*(?:hash|Hash|ptrHash|keyHash)') { continue }
    if (-not $hasIter) { continue }
    $n13 += $c
  }
}
Write-Host "1.3 narrowed: $($n13.Count) (from $($uDecls.Count))"

# Export priority triage packs by pattern (low-count + narrowed high-count samples)
$priorityIds = @('1.4','1.5','1.6','1.7','1.9','1.11','1.12','3.1','3.5','3.7','4.1','4.2','4.4')
$packs = @{}
foreach ($id in $priorityIds) {
  $packs[$id] = @($cands | Where-Object pattern_id -eq $id)
}
$packs['1.1'] = $n11
$packs['1.2'] = $n12 | Select-Object -First 200
$packs['1.3'] = $n13 | Select-Object -First 120
$packs['3.2'] = @($cands | Where-Object pattern_id -eq '3.2' | Select-Object -First 80)

$summary = [ordered]@{}
foreach ($k in ($packs.Keys | Sort-Object)) { $summary[$k] = $packs[$k].Count }
$summary | ConvertTo-Json | Write-Host

$export = [ordered]@{
  module_path = $root
  narrowed_counts = $summary
  packs = $packs
}
$exportPath = "C:\Users\carys\.cursor\plans\nd_cts_narrowed_packs.json"
# Convert carefully - packs values are arrays of PSCustomObject
$json = $export | ConvertTo-Json -Depth 8 -Compress
[System.IO.File]::WriteAllText($exportPath, $json)
Write-Host "Wrote $exportPath size=$((Get-Item $exportPath).Length)"

# Also dump file lists for parallel agents
$hotFiles = @{}
foreach ($id in $packs.Keys) {
  foreach ($c in $packs[$id]) {
    if (-not $hotFiles.ContainsKey($c.file)) { $hotFiles[$c.file] = [System.Collections.Generic.List[string]]::new() }
    $hotFiles[$c.file].Add("$($c.pattern_id):$($c.line)")
  }
}
Write-Host "Hot files for triage: $($hotFiles.Count)"
$hotFiles.GetEnumerator() | Sort-Object { $_.Value.Count } -Descending | Select-Object -First 25 | ForEach-Object { "{0} ({1})" -f $_.Key, $_.Value.Count }
